34	export async function persistAcceptedResponse(
35		transaction: AcquisitionTransaction,
36		descriptor: ExactRequestDescriptor,
37		state: AcquisitionState,
38		body: Buffer,
39	): Promise<DurableResponseRecord> {
40		await mkdir(transaction.durableRoot, { recursive: true });
41		const record = responseRecord(descriptor, state.acceptedResponses + 1, body);
42		const bodyPath = join(transaction.durableRoot, record.bodyFile);
43		const partialPath = `${bodyPath}.partial`;
44		const bodyHandle = await open(partialPath, 'wx');
45		try {
46			await bodyHandle.writeFile(body);
47			await bodyHandle.sync();
48		} finally {
49			await bodyHandle.close();
50		}
51		await rename(partialPath, bodyPath);
52		await fsyncDirectory(transaction.durableRoot);
53		const journal = await open(join(transaction.durableRoot, 'journal.ndjson'), 'a');
54		try {
55			await journal.writeFile(`${canonicalResponseRecord(record)}\n`);
56			await journal.sync();
57		} finally {
58			await journal.close();
59		}
60		return record;
61	}
62	
63	export async function acquireExactResponse(
64		transaction: AcquisitionTransaction,
65		descriptor: ExactRequestDescriptor,
66		state: AcquisitionState,
67	): Promise<Buffer> {
68		const url = exactRequestUrl(descriptor);
69		const cap =
70			descriptor.responseKind === 'archive' ? transaction.archiveCap : transaction.metadataCap;
71		for (let attempt = 1; attempt <= 3; attempt += 1) {
72			try {
73				return await new Promise<Buffer>((resolvePromise, reject) => {
74					let responseObserved = false;
75					const call = request(
76						url,
77						{
78							method: 'GET',
79							headers: {
80								accept:
81									descriptor.responseKind === 'json'
82										? 'application/vnd.github+json'
83										: 'application/octet-stream',
84								'accept-encoding': 'identity',
85								'user-agent': 'versionless-shared-acquisition',
86								'x-versionless-consent-id': transaction.consentId,
87							},
88						},
89						(response) => {
90							responseObserved = true;
91							const observation: AcquisitionObservation = {
92								method: 'GET',
93								url,
94								purpose: descriptor.purpose,
95								attempt,
96								status: response.statusCode ?? 0,
97								headersObserved: true,
98								bodyBytes: 0,
99								acceptedResponse: false,
100							};
101							state.observations.push(observation);
102							if (response.statusCode !== 200) {
103								response.destroy();
104								reject(
105									new AcquisitionFailure(
106										'transport',
107										response.statusCode &&
108											response.statusCode >= 300 &&
109											response.statusCode < 400
110											? 'redirect-status'
111											: 'non-200-status',
112										200,
113										response.statusCode ?? 0,
114										'Acquisition response status differs',
115									),
116								);
117								return;
118							}
119							if ((response.headers['content-encoding'] ?? 'identity') !== 'identity') {
120								response.destroy();
121								reject(
122									new AcquisitionFailure(
123										'transport',
124										'content-encoding',
125										'identity',
126										'non-identity',
127										'Acquisition content encoding differs',
128									),
129								);
130								return;
131							}
132							let bytes = 0;
133							const chunks: Buffer[] = [];
134							response.on('data', (chunk: Buffer) => {
135								bytes += chunk.byteLength;
136								(observation as { bodyBytes: number }).bodyBytes = bytes;
137								if (
138									bytes > cap ||
139									state.aggregateBytes + bytes > transaction.aggregateCap
140								)
141									response.destroy(
142										new AcquisitionFailure(
143											'transport',
144											'body-cap',
145											`<=${cap}`,
146											bytes,
147											'Acquisition response cap exceeded',
148										),
149									);
150								else chunks.push(Buffer.from(chunk));
151							});
152							response.once('error', reject);
153							response.once('end', async () => {
154								try {
155									const body = Buffer.concat(chunks, bytes);
156									const record = await persistAcceptedResponse(
157										transaction,
158										descriptor,
159										state,
160										body,
161									);
162									(observation as { acceptedResponse: boolean }).acceptedResponse =
163										true;
164									state.acceptedResponses += 1;
165									state.aggregateBytes += bytes;
166									state.ledger.push(record);
167									resolvePromise(body);
168								} catch (error) {
169									reject(error);
170								}
171							});
172						},
173					);
174					call.setTimeout(60_000, () => call.destroy(new Error('zero-observation timeout')));
175					call.once('error', (error) => {
176						if (!responseObserved) {
177							state.observations.push({
178								method: 'GET',
179								url,
180								purpose: descriptor.purpose,
181								attempt,
182								status: null,
183								headersObserved: false,
184								bodyBytes: 0,
185								acceptedResponse: false,
186							});
187							Object.assign(error, { zeroObservation: true });
188						}
189						reject(error);
190					});
191					call.end();
192				});
193			} catch (error) {
194				if (!(error instanceof Error) || !('zeroObservation' in error) || attempt === 3)
195					throw error;
196			}
197		}
198		throw new AcquisitionFailure(
199			'transport',
200			'zero-observation-retries',
201			3,
202			3,
203			'Acquisition transport exhausted',
204		);
205	}
206	
207	export async function verifyDurableResponses(
208		transaction: AcquisitionTransaction,
209		records: readonly DurableResponseRecord[],
210	): Promise<void> {
211		for (const record of records) {
212			const bytes = await readFile(join(transaction.durableRoot, record.bodyFile));
213			const replay = {
214				bodyBytes: bytes.byteLength,
215				sha256: sha256(bytes),
216				sha512: createHash('sha512').update(bytes).digest('hex'),
217			};
218			if (
219				replay.bodyBytes !== record.bodyBytes ||
220				replay.sha256 !== record.sha256 ||
221				replay.sha512 !== record.sha512
222			)
223				throw new AcquisitionFailure(
224					'offline-replay',
225					'durable-response-record',
226					{ bodyBytes: record.bodyBytes, sha256: record.sha256, sha512: record.sha512 },
227					replay,
228					'Durable acquisition replay differs',
229				);
230		}
231	}
