1	// Generic legacy-corpus candidate ingest machinery.
2	//
3	// One admitted legacy application is described by a LegacyCandidateConfig; every stage below is a
4	// pure function of that configuration plus injected bytes, so the acquisition shape, the archive to
5	// git-tree reconciliation, the dependency closure, and the baseline install/build record can all be
6	// exercised offline. Only the default transport, extractor, and step runner touch the host, and the
7	// acquisition entry point refuses to run without exact purpose-bound consent.
8	import { execFileSync, spawnSync } from 'node:child_process';
9	import { createHash } from 'node:crypto';
10	import { mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
11	import { request } from 'node:https';
12	import { charIn, createRegExp } from 'magic-regexp';
13	import { join, relative, resolve } from 'pathe';
14	import { joinURL, parseURL, withQuery } from 'ufo';
15	import { sha256 } from '../../../core/src/receipts/canonicalize.ts';
16	
17	export const LEGACY_CORPUS_CONSENT = 'VL-LEGACY-CORPUS-2026-08-10' as const;
18	
19	export const lowerHex40 = createRegExp(
20		charIn('0123456789').from('a', 'f').times(40).at.lineStart().at.lineEnd(),
21	);
22	export const lowerHex64 = createRegExp(
23		charIn('0123456789').from('a', 'f').times(64).at.lineStart().at.lineEnd(),
24	);
25	
26	export type LegacyCandidateId = 'react-papercups-v1-0-0';
27	
28	export type LegacyAcquisitionCaps = Readonly<{
29		maximumAcceptedResponses: number;
30		maximumApiResponseBytes: number;
31		maximumArchiveBytes: number;
32		maximumAggregateWireBytes: number;
33		maximumAggregateDecodedBytes: number;
34		requiredArchiveStreams: number;
35	}>;
36	
37	export type LegacyCandidateConfig = Readonly<{
38		id: LegacyCandidateId;
39		consentId: typeof LEGACY_CORPUS_CONSENT;
40		owner: string;
41		repository: string;
42		tag: string;
43		frontendRoot: string;
44		lockFileName: string;
45		caps: LegacyAcquisitionCaps;
46		requiredRevisionWindow: Readonly<{ from: string; through: string }>;
47		legacyCell: Readonly<{
48			installCommand: readonly string[];
49			buildCommand: readonly string[];
50			buildOutputDirectory: string;
51		}>;
52	}>;
53	
54	const defaultCaps: LegacyAcquisitionCaps = {
55		maximumAcceptedResponses: 7,
56		maximumApiResponseBytes: 16_777_216,
57		maximumArchiveBytes: 134_217_728,
58		maximumAggregateWireBytes: 314_572_800,
59		maximumAggregateDecodedBytes: 314_572_800,
60		requiredArchiveStreams: 2,
61	};
62	
63	/**
64	 * The applications this module's *network acquisition* path is consented for.
65	 *
66	 * This list is no longer an admission gate. Admission runs through the
67	 * `ingest` and `license-at-pin` operator stages
68	 * (`packages/cli/src/operator/ingest.ts`), which read an application source that
69	 * is already on disk and require no entry here, no per-application module, and
70	 * no source edit. What still reads this list is the network half and the
71	 * evidence it published:
72	 *
73	 * - `versionless fixture:ingest --fixture <id>` (`packages/cli/src/cli.ts`),
74	 *   which acquires an official source over the network under the exact
75	 *   purpose-bound consent each entry carries;
76	 * - `versionless fixture:verify --fixture <id>`, which re-verifies the sealed
77	 *   `evidence/ingests/<id>/` documents that acquisition published;
78	 * - `isLegacyCandidateId` and `legacyCandidateConfig` below, which serve those
79	 *   two commands and their tests.
80	 *
81	 * An entry is therefore a record of consent already given for a named remote
82	 * repository, not a permission to migrate. Nothing an operator runs against a
83	 * local application source consults it.
84	 */
85	export const legacyCandidates: readonly LegacyCandidateConfig[] = [
86		{
87			id: 'react-papercups-v1-0-0',
88			consentId: LEGACY_CORPUS_CONSENT,
89			owner: 'papercups-io',
90			repository: 'papercups',
91			tag: 'v1.0.0',
92			frontendRoot: 'assets',
93			lockFileName: 'package-lock.json',
94			caps: defaultCaps,
95			requiredRevisionWindow: { from: '2018-01-01T00:00:00Z', through: '2023-08-10T00:00:00Z' },
96			legacyCell: {
97				installCommand: ['ci', '--ignore-scripts', '--no-audit', '--no-fund'],
98				buildCommand: ['run', 'build'],
99				buildOutputDirectory: 'build',
100			},
101		},
102	] as const;
103	
104	export function isLegacyCandidateId(id: string | undefined): id is LegacyCandidateId {
105		return legacyCandidates.some((candidate) => candidate.id === id);
106	}
107	
108	export function legacyCandidateConfig(id: string | undefined): LegacyCandidateConfig {
109		const candidate = legacyCandidates.find((entry) => entry.id === id);
110		if (!candidate) throw new Error(`Unknown legacy corpus candidate: ${String(id)}`);
111		return candidate;
112	}
113	
114	export const workspaceRoot = resolve(import.meta.dirname, '../../../..');
115	export const evidenceRootFor = (config: LegacyCandidateConfig): string =>
116		`evidence/ingests/${config.id}`;
117	export const cacheRootFor = (config: LegacyCandidateConfig): string =>
118		`.versionless/cache/${config.id}-source`;
119	export const workRootFor = (config: LegacyCandidateConfig): string =>
120		`.versionless/work/${config.id}/legacy`;
121	
122	const apiOrigin = 'https://api.github.com';
123	const archiveOrigin = 'https://codeload.github.com';
124	const acquisitionHosts: readonly string[] = ['api.github.com', 'codeload.github.com'];
125	
126	export const repositoryEndpoint = (config: LegacyCandidateConfig): string =>
127		joinURL(apiOrigin, 'repos', config.owner, config.repository);
128	export const tagRefEndpoint = (config: LegacyCandidateConfig): string =>
129		joinURL(repositoryEndpoint(config), 'git/ref/tags', config.tag);
130	export const tagObjectEndpoint = (config: LegacyCandidateConfig, sha: string): string =>
131		joinURL(repositoryEndpoint(config), 'git/tags', sha);
132	export const commitEndpoint = (config: LegacyCandidateConfig, sha: string): string =>
133		joinURL(repositoryEndpoint(config), 'git/commits', sha);
134	export const treeEndpoint = (config: LegacyCandidateConfig, sha: string): string =>
135		withQuery(joinURL(repositoryEndpoint(config), 'git/trees', sha), { recursive: '1' });
136	export const blobEndpoint = (config: LegacyCandidateConfig, sha: string): string =>
137		joinURL(repositoryEndpoint(config), 'git/blobs', sha);
138	export const archiveEndpoint = (config: LegacyCandidateConfig, commitSha: string): string =>
139		joinURL(archiveOrigin, config.owner, config.repository, 'tar.gz', commitSha);
140	
141	export function candidateAllowlist(config: LegacyCandidateConfig): readonly string[] {
142		return [
143			repositoryEndpoint(config),
144			tagRefEndpoint(config),
145			commitEndpoint(config, '<validated-commit-sha>'),
146			treeEndpoint(config, '<validated-tree-sha>'),
147			archiveEndpoint(config, '<validated-commit-sha>'),
148		];
149	}
150	
151	export function assertAllowedAcquisitionUrl(url: string, config: LegacyCandidateConfig): void {
152		const parsed = parseURL(url);
153		const repositoryPath = `/repos/${config.owner}/${config.repository}`;
154		const archivePath = `/${config.owner}/${config.repository}/tar.gz/`;
155		if (
156			parsed.protocol !== 'https:' ||
157			!acquisitionHosts.includes(parsed.host ?? '') ||
158			parsed.auth ||
159			parsed.hash ||
160			(parsed.host === 'api.github.com'
161				? !(
162						parsed.pathname === repositoryPath ||
163						parsed.pathname.startsWith(`${repositoryPath}/`)
164					)
165				: !parsed.pathname.startsWith(archivePath))
166		)
167			throw new Error(`Legacy acquisition URL is outside literal consent: ${url}`);
168	}
169	
170	export type LegacyAcquisitionAttempt = Readonly<{
171		schemaVersion: 'versionless.official-source-attempt.v1';
172		candidate: Readonly<{ repository: string; requestedTag: string }>;
173		consentId: string;
174		result: 'started';
175		network: Readonly<{
176			method: 'GET';
177			credentials: 'none';
178			requestEncoding: 'identity';
179			redirectsAllowed: false;
180			retriesAllowed: false;
181			alternateHostsAllowed: false;
182		}>;
183		allowlist: readonly string[];
184		caps: LegacyAcquisitionCaps;
185		requiredRevisionWindow: Readonly<{ from: string; through: string }>;
186		publication: Readonly<{
187			evidenceRoot: string;
188			cacheRoot: string;
189			transactional: true;
190			readinessCredit: false;
191		}>;
192		nonclaims: readonly string[];
193	}>;
194	
195	export function acquisitionAttempt(config: LegacyCandidateConfig): LegacyAcquisitionAttempt {
196		return {
197			schemaVersion: 'versionless.official-source-attempt.v1',
198			candidate: {
199				repository: `${config.owner}/${config.repository}`,
200				requestedTag: config.tag,
201			},
202			consentId: config.consentId,
203			result: 'started',
204			network: {
205				method: 'GET',
206				credentials: 'none',
207				requestEncoding: 'identity',
208				redirectsAllowed: false,
209				retriesAllowed: false,
210				alternateHostsAllowed: false,
211			},
212			allowlist: candidateAllowlist(config),
213			caps: config.caps,
214			requiredRevisionWindow: config.requiredRevisionWindow,
215			publication: {
216				evidenceRoot: evidenceRootFor(config),
217				cacheRoot: cacheRootFor(config),
218				transactional: true,
219				readinessCredit: false,
220			},
221			nonclaims: [
