269	export function normalizedManifest(files: readonly ExtractedFile[]): NormalizedManifest {
270		const lines = files
271			.map((file) => `${file.path} ${sha256(Buffer.from(file.bytes))} ${file.bytes.byteLength}`)
272			.sort();
