277	export type ArchiveParity = Readonly<{
278		singleRoot: string;
279		safeEntries: number;
280		regularFiles: number;
281		directories: number;
282		specialEntries: number;
283		gitBlobs: number;
284		missingFiles: number;
285		extraFiles: number;
286		mismatchedBlobs: number;
287		normalizedManifestSha256: string;
288	}>;
289	
290	export function reconcileArchiveWithTree(input: {
291		singleRoot: string;
292		rows: readonly TreeRow[];
293		files: readonly ExtractedFile[];
294		directories: number;
295		specialEntries: number;
296	}): ArchiveParity {
297		const blobs = regularBlobIndex(input.rows);
298		const seen = new Set<string>();
299		let mismatchedBlobs = 0;
300		let extraFiles = 0;
301		for (const file of input.files) {
302			const expected = blobs.get(file.path);
303			if (expected === undefined) extraFiles += 1;
304			else {
305				seen.add(file.path);
306				if (gitBlobId(file.bytes) !== expected) mismatchedBlobs += 1;
307			}
308		}
309		return {
310			singleRoot: input.singleRoot,
311			safeEntries: input.files.length + input.directories,
312			regularFiles: input.files.length,
313			directories: input.directories,
314			specialEntries: input.specialEntries,
315			gitBlobs: blobs.size,
316			missingFiles: blobs.size - seen.size,
317			extraFiles,
318			mismatchedBlobs,
319			normalizedManifestSha256: normalizedManifest(input.files).sha256,
320		};
321	}
