326	type LockNode = Readonly<{
327		version?: unknown;
328		resolved?: unknown;
329		integrity?: unknown;
330		dependencies?: unknown;
331		dev?: unknown;
332		optional?: unknown;
333		bundled?: unknown;
334	}>;
335	
336	export type LockPlacement = Readonly<{
337		name: string;
338		version: string;
339		path: string;
340		resolved: string | null;
341		integrity: string | null;
342		dev: boolean;
343		optional: boolean;
344		bundled: boolean;
345	}>;
346	
347	export function collectLockPlacements(lock: unknown): LockPlacement[] {
348		const placements: LockPlacement[] = [];
349		const walk = (dependencies: unknown, parents: readonly string[]): void => {
350			if (dependencies === undefined || dependencies === null) return;
351			if (typeof dependencies !== 'object' || Array.isArray(dependencies))
352				throw new Error('Legacy lock dependencies must be an object');
353			for (const [name, value] of Object.entries(dependencies as Record<string, unknown>)) {
354				if (!value || typeof value !== 'object' || Array.isArray(value))
355					throw new Error(`Legacy lock node differs: ${[...parents, name].join('/')}`);
356				const node = value as LockNode;
357				if (typeof node.version !== 'string')
358					throw new Error(`Legacy lock version differs: ${[...parents, name].join('/')}`);
359				placements.push({
360					name,
361					version: node.version,
362					path: [...parents, name].join('/'),
363					resolved: typeof node.resolved === 'string' ? node.resolved : null,
364					integrity: typeof node.integrity === 'string' ? node.integrity : null,
365					dev: node.dev === true,
366					optional: node.optional === true,
367					bundled: node.bundled === true,
368				});
369				walk(node.dependencies, [...parents, name]);
370			}
371		};
372		if (!lock || typeof lock !== 'object' || Array.isArray(lock))
373			throw new Error('Legacy lock document must be an object');
374		walk((lock as { dependencies?: unknown }).dependencies, []);
375		return placements;
376	}
