378	/**
379	 * What `analyzeLegacyLockClosure` actually reads off a candidate.
380	 *
381	 * The closure analysis never needed the acquisition half of a
382	 * `LegacyCandidateConfig` — no consent id, no owner, no caps, no revision
383	 * window. Naming the three fields it does read is what lets the generic
384	 * `ingest` operator stage produce the same `versionless.legacy-dependency-closure.v1`
385	 * record for an application that has no entry in `legacyCandidates` and no
386	 * per-application module. A `LegacyCandidateConfig` still satisfies it, so
387	 * every existing caller is unchanged.
388	 */
389	export type LegacyClosureIdentity = Readonly<{
390		id: string;
391		frontendRoot: string;
392		lockFileName: string;
393	}>;
394	
395	export type LegacyClosureRecord = Readonly<{
396		schemaVersion: 'versionless.legacy-dependency-closure.v1';
397		slug: string;
398		frontendRoot: string;
399		source: Readonly<{
400			verifiedSourceRoot: string;
401			packageJsonSha256: string;
402			packageLockSha256: string;
403			packageLockBytes: number;
404		}>;
405		lockState: Readonly<{
406			file: string;
407			lockfileVersion: number | null;
408			requiresField: boolean | null;
409			committedWithSource: true;
410			coversDevDependencies: boolean;
411			everyEntryHasResolvedUrl: boolean;
412			everyEntryHasIntegrityHash: boolean;
413			entriesWithoutResolvedUrl: readonly string[];
414			entriesWithoutIntegrityHash: readonly string[];
415			lockfileIntegrityAlgorithms: readonly string[];
416		}>;
417		counts: Readonly<{
418			declaredDependencies: number;
419			declaredDevDependencies: number;
420			lockedPlacements: number;
421			distinctNameVersionPairs: number;
422			devPlacements: number;
423			optionalPlacements: number;
424			bundledPlacements: number;
425		}>;
426		registryHosts: Readonly<Record<string, number>>;
427		closureSha256: string;
428		nonclaims: readonly string[];
429	}>;
430	
431	export function analyzeLegacyLockClosure(
432		config: LegacyClosureIdentity,
433		input: {
434			verifiedSourceRoot: string;
435			packageBytes: Uint8Array;
436			lockBytes: Uint8Array;
437		},
438	): LegacyClosureRecord {
439		const manifest = JSON.parse(Buffer.from(input.packageBytes).toString('utf8')) as {
440			dependencies?: Record<string, unknown>;
441			devDependencies?: Record<string, unknown>;
442		};
443		const lock = JSON.parse(Buffer.from(input.lockBytes).toString('utf8')) as {
444			lockfileVersion?: unknown;
445			requires?: unknown;
446		};
447		const placements = collectLockPlacements(lock);
448		const hosts = new Map<string, number>();
449		for (const placement of placements) {
450			if (placement.resolved === null) continue;
451			const host = parseURL(placement.resolved).host ?? '';
452			hosts.set(host, (hosts.get(host) ?? 0) + 1);
453		}
454		const withoutResolved = placements.filter(
455			(placement) => placement.resolved === null && !placement.bundled,
456		);
457		const withoutIntegrity = placements.filter(
458			(placement) => placement.integrity === null && !placement.bundled,
459		);
460		const closureLines = placements
461			.map(
462				(placement) =>
463					`${placement.path} ${placement.version} ${placement.integrity ?? 'none'}`,
464			)
465			.sort();
466		return {
467			schemaVersion: 'versionless.legacy-dependency-closure.v1',
468			slug: config.id,
469			frontendRoot: config.frontendRoot,
470			source: {
471				verifiedSourceRoot: input.verifiedSourceRoot,
472				packageJsonSha256: sha256(Buffer.from(input.packageBytes)),
473				packageLockSha256: sha256(Buffer.from(input.lockBytes)),
474				packageLockBytes: input.lockBytes.byteLength,
475			},
476			lockState: {
477				file: config.lockFileName,
478				lockfileVersion: typeof lock.lockfileVersion === 'number' ? lock.lockfileVersion : null,
479				requiresField: typeof lock.requires === 'boolean' ? lock.requires : null,
480				committedWithSource: true,
481				coversDevDependencies: placements.some((placement) => placement.dev),
482				everyEntryHasResolvedUrl: withoutResolved.length === 0,
483				everyEntryHasIntegrityHash: withoutIntegrity.length === 0,
484				entriesWithoutResolvedUrl: withoutResolved.map((placement) => placement.path),
485				entriesWithoutIntegrityHash: withoutIntegrity.map((placement) => placement.path),
486				lockfileIntegrityAlgorithms: [
487					...new Set(
488						placements.map(
489							(placement) => (placement.integrity ?? 'none').split('-')[0] ?? 'none',
490						),
491					),
492				].sort(),
493			},
494			counts: {
495				declaredDependencies: Object.keys(manifest.dependencies ?? {}).length,
496				declaredDevDependencies: Object.keys(manifest.devDependencies ?? {}).length,
497				lockedPlacements: placements.length,
498				distinctNameVersionPairs: new Set(
499					placements.map((placement) => `${placement.name}@${placement.version}`),
500				).size,
501				devPlacements: placements.filter((placement) => placement.dev).length,
502				optionalPlacements: placements.filter((placement) => placement.optional).length,
503				bundledPlacements: placements.filter((placement) => placement.bundled).length,
504			},
505			registryHosts: Object.fromEntries(
506				[...hosts].sort(([left], [right]) => compare(left, right)),
507			),
508			closureSha256: sha256(Buffer.from(`${closureLines.join('\n')}\n`, 'utf8')),
509			nonclaims: [
510				'Per-artifact byte digests were not independently mirrored in this unit; the recorded integrity hashes are the ones the committed lockfile declares.',
511				'A resolvable closure establishes no build, browser behavior, licence compatibility of transitive dependencies, migration feasibility, or production readiness.',
512			],
513		};
514	}
