595	// A build step only runs when the install step succeeded: a failing install is recorded, not repaired.
596	export function runLegacyBaselineSteps(
597		config: LegacyCandidateConfig,
598		runner: LegacyStepRunner,
599		clock: LegacyClock = systemClock(),
600	): LegacyBaselineStep[] {
601		const steps: LegacyBaselineStep[] = [];
602		const execute = (name: string, args: readonly string[]): LegacyBaselineStep => {
603			const startedAt = clock.now().toISOString();
604			const started = clock.elapsedMs();
605			const outcome = runner(args);
606			return recordLegacyStep({
607				name,
608				args,
609				startedAt,
610				durationMs: clock.elapsedMs() - started,
611				outcome,
612			});
613		};
614		const install = execute('install', config.legacyCell.installCommand);
615		steps.push(install);
616		if (install.exitCode === 0) steps.push(execute('build', config.legacyCell.buildCommand));
617		return steps;
618	}
