683	export type LegacyTransport = (
684		url: string,
685		kind: 'json' | 'archive',
686		state: LegacyAcquisitionState,
687		stream?: number,
688	) => Promise<Buffer>;
689	
690	export function newAcquisitionState(): LegacyAcquisitionState {
691		return { requests: [], aggregateBytes: 0, redirectsObserved: 0, setCookiesUsed: 0 };
692	}
693	
694	export function httpsTransport(config: LegacyCandidateConfig): LegacyTransport {
695		return (url, kind, state, stream) =>
696			new Promise<Buffer>((resolvePromise, reject) => {
697				assertAllowedAcquisitionUrl(url, config);
698				const cap =
699					kind === 'json'
700						? config.caps.maximumApiResponseBytes
701						: config.caps.maximumArchiveBytes;
702				const call = request(
703					url,
704					{
705						method: 'GET',
706						headers: {
707							accept:
708								kind === 'json'
709									? 'application/vnd.github+json'
710									: 'application/octet-stream',
711							'accept-encoding': 'identity',
712							'user-agent': 'versionless-shared-acquisition',
713							'x-versionless-consent-id': config.consentId,
714						},
715					},
716					(response) => {
717						const status = response.statusCode ?? 0;
718						if (status >= 300 && status < 400) state.redirectsObserved += 1;
719						if (response.headers['set-cookie']) state.setCookiesUsed += 1;
720						if (status !== 200) {
721							response.resume();
722							reject(new Error(`Legacy acquisition status differs: ${status} ${url}`));
723							return;
724						}
725						if ((response.headers['content-encoding'] ?? 'identity') !== 'identity') {
726							response.resume();
727							reject(new Error(`Legacy acquisition content encoding differs: ${url}`));
728							return;
729						}
730						const chunks: Buffer[] = [];
731						let bytes = 0;
732						response.on('data', (chunk: Buffer) => {
733							bytes += chunk.byteLength;
734							if (
735								bytes > cap ||
736								state.aggregateBytes + bytes > config.caps.maximumAggregateWireBytes
737							)
738								response.destroy(new Error(`Legacy acquisition cap exceeded: ${url}`));
739							else chunks.push(Buffer.from(chunk));
740						});
741						response.once('error', reject);
742						response.once('end', () => {
743							const body = Buffer.concat(chunks, bytes);
744							state.aggregateBytes += bytes;
745							state.requests.push({
746								endpoint: url,
747								status: 200,
748								bytes,
749								sha256: sha256(body),
750								...(stream === undefined ? {} : { stream }),
751							});
752							if (state.requests.length > config.caps.maximumAcceptedResponses) {
753								reject(new Error('Legacy acquisition accepted-response cap exceeded'));
754								return;
755							}
756							resolvePromise(body);
757						});
758					},
759				);
760				call.setTimeout(120_000, () =>
761					call.destroy(new Error(`Legacy acquisition timeout: ${url}`)),
762				);
763				call.once('error', reject);
764				call.end();
765			});
766	}
