843	async function walkExtracted(
844		directory: string,
845		base: string,
846	): Promise<{ files: ExtractedFile[]; directories: number; specialEntries: number }> {
847		const files: ExtractedFile[] = [];
848		let directories = 0;
849		let specialEntries = 0;
850		for (const entry of await readdir(directory, { withFileTypes: true })) {
851			const full = join(directory, entry.name);
852			if (entry.isDirectory()) {
853				directories += 1;
854				const nested = await walkExtracted(full, base);
855				files.push(...nested.files);
856				directories += nested.directories;
857				specialEntries += nested.specialEntries;
858			} else if (entry.isFile())
859				files.push({ path: relative(base, full), bytes: await readFile(full) });
860			else specialEntries += 1;
861		}
862		return { files, directories, specialEntries };
863	}
864	
865	// Acquires one candidate's official source under exact purpose-bound consent and publishes the
866	// attempt and source documents. Every remote byte flows through the injected transport, so the
867	// composition above stays testable without a network.
868	export async function acquireLegacyCandidateSource(
869		config: LegacyCandidateConfig,
870		options: {
871			allowNetwork: boolean;
872			consentId?: string;
873			transport?: LegacyTransport;
874			extract?: LegacyExtractor;
875			root?: string;
876		},
877	): Promise<{
878		manifest: { id: LegacyCandidateId };
879		consent: { consentId: string };
880		source: LegacySourceRecord;
881	}> {
882		assertLegacyAcquisitionConsent(config, options);
883		const root = options.root ?? workspaceRoot;
884		const transport = options.transport ?? httpsTransport(config);
885		const extract = options.extract ?? tarExtractor;
886		const evidenceDirectory = join(root, evidenceRootFor(config));
887		const cacheDirectory = join(root, cacheRootFor(config));
888		const archiveDirectory = join(cacheDirectory, 'archive');
889		const extractDirectory = join(cacheDirectory, 'verify/extracted');
890		await mkdir(archiveDirectory, { recursive: true });
891		await mkdir(evidenceDirectory, { recursive: true });
892	
893		const state = newAcquisitionState();
894		const startedAt = new Date().toISOString();
895		const readJson = async (url: string): Promise<Record<string, unknown>> =>
896			JSON.parse((await transport(url, 'json', state)).toString('utf8')) as Record<
897				string,
898				unknown
899			>;
900		const repository = await readJson(repositoryEndpoint(config));
901		const reference = await readJson(tagRefEndpoint(config));
902		const referenceObject = reference.object as { sha: string; type: string };
903		let tagObject: Record<string, unknown> | undefined;
904		let commitSha = referenceObject.sha;
905		if (referenceObject.type === 'tag') {
906			tagObject = await readJson(tagObjectEndpoint(config, referenceObject.sha));
907			commitSha = (tagObject.object as { sha: string }).sha;
908		}
909		const commit = await readJson(commitEndpoint(config, commitSha));
910		const rootTreeSha = (commit.tree as { sha: string }).sha;
911		const tree = await readJson(treeEndpoint(config, rootTreeSha));
912		if (tree.truncated === true)
913			throw new Error('Legacy git tree is truncated; refusing partial reconciliation');
914		const rows = tree.tree as TreeRow[];
915	
916		const archives: { file: string; sha256: string; bytes: number }[] = [];
917		for (let stream = 1; stream <= config.caps.requiredArchiveStreams; stream += 1) {
918			const body = await transport(archiveEndpoint(config, commitSha), 'archive', state, stream);
919			const file = join(archiveDirectory, `archive-${stream}.tar.gz`);
920			await writeFile(file, body);
921			archives.push({ file, sha256: sha256(body), bytes: body.byteLength });
922		}
923		const archivesByteIdentical = archives.every(
924			(archive) => archive.sha256 === (archives[0]?.sha256 ?? ''),
925		);
926		if (!archivesByteIdentical)
927			throw new Error('Legacy archive streams differ; refusing to publish source');
928	
929		await rm(extractDirectory, { recursive: true, force: true });
930		await mkdir(extractDirectory, { recursive: true });
931		extract(archives[0]?.file ?? '', extractDirectory);
932		const roots = await readdir(extractDirectory);
933		const singleRoot = roots[0];
934		if (roots.length !== 1 || singleRoot === undefined)
935			throw new Error(`Legacy archive has ${roots.length} roots`);
936		const sourceRoot = join(extractDirectory, singleRoot);
937		const walked = await walkExtracted(sourceRoot, sourceRoot);
938		const parity = reconcileArchiveWithTree({
939			singleRoot,
940			rows,
941			files: walked.files,
942			directories: walked.directories + 1,
943			specialEntries: walked.specialEntries,
944		});
945		await writeFile(join(cacheDirectory, 'manifest.txt'), normalizedManifest(walked.files).text);
946	
947		const attempt = acquisitionAttempt(config);
948		const attemptBytes = Buffer.from(documentBytes(attempt), 'utf8');
949		await writeFile(join(evidenceDirectory, 'attempt.json'), attemptBytes);
950		const first = state.requests[0];
951		if (!first) throw new Error('Legacy acquisition recorded no accepted responses');
952		const verification = (value: unknown): 'verified' | 'unsigned' =>
953			(value as { verified?: boolean } | undefined)?.verified === true ? 'verified' : 'unsigned';
954		const source: LegacySourceRecord = {
955			schemaVersion: 'versionless.official-source.v1',
956			consentId: config.consentId,
957			attemptSha256: sha256(attemptBytes),
958			result: 'source-bound',
959			startedAt,
960			completedAt: new Date().toISOString(),
961			repository: {
962				id: repository.id as number,
963				fullName: repository.full_name as string,
964				private: repository.private === true,
965				archived: repository.archived === true,
966				disabled: repository.disabled === true,
967				responseBytes: first.bytes,
968				responseSha256: first.sha256,
969			},
970			revision: {
971				ref: `refs/tags/${config.tag}`,
972				tagObjectSha: (tagObject?.sha as string | undefined) ?? null,
973				tagKind: tagObject ? 'annotated' : 'lightweight',
974				tagDate: ((tagObject?.tagger as { date?: string } | undefined)?.date ?? null) as
975					| string
976					| null,
977				tagVerification: verification(tagObject?.verification),
978				commitSha,
979				commitDate: ((commit.committer as { date?: string } | undefined)?.date ?? null) as
980					| string
981					| null,
982				commitVerification: verification(commit.verification),
983				rootTreeSha,
984				...summarizeTree(rows),
985				treeTruncated: tree.truncated === true,
986			},
987			requests: state.requests,
988			archiveParity: parity,
989			transaction: {
990				attemptedRequests: state.requests.length,
991				acceptedResponses: state.requests.length,
992				acceptedWireBytes: state.aggregateBytes,
993				acceptedDecodedBytes: state.aggregateBytes,
994				redirectsObserved: state.redirectsObserved,
995				setCookiesUsed: state.setCookiesUsed,
996				retries: 0,
997				archivesByteIdentical,
998				archiveMatchesGitTree: archiveMatchesGitTree(parity),
999				publishedSource: true,
1000				readinessCredit: false,
1001				implementationStarted: false,
1002			},
1003			cache: {
1004				root: cacheRootFor(config),
1005				archive1: relative(root, archives[0]?.file ?? ''),
1006				archive2: relative(root, archives[1]?.file ?? ''),
1007				verifiedSource: relative(root, extractDirectory),
1008				rawMetadataPortable: false,
1009			},
1010			nonclaims: [
1011				'A lightweight or unsigned tag does not establish signer authenticity.',
1012				'No dependency closure, build, browser behavior, migration feasibility, pilot status, production readiness, certification, or legal approval is established by this record.',
1013			],
1014		};
1015		await writeFile(join(evidenceDirectory, 'source.json'), documentBytes(source));
1016		return { manifest: { id: config.id }, consent: { consentId: config.consentId }, source };
1017	}
1018	
1019	export async function ingestLegacyCandidate(options: {
1020		fixture?: string;
1021		allowNetwork: boolean;
1022		consentId?: string;
1023	}): Promise<{ manifest: { id: LegacyCandidateId }; consent: { consentId: string } }> {
1024		const config = legacyCandidateConfig(options.fixture);
1025		return acquireLegacyCandidateSource(config, options);
1026	}
