309	function isNode(value: unknown): value is Node {
310		return (
311			value !== null &&
312			typeof value === 'object' &&
313			typeof (value as { type?: unknown }).type === 'string'
314		);
315	}
316	
317	/** Collapse every whitespace run to one space, so a guard reads on one line. */
318	export function collapseWhitespace(value: string): string {
319		const parts: string[] = [];
320		let current = '';
321		for (const character of value) {
322			const white =
323				character === ' ' ||
324				character === '\t' ||
325				character === '\n' ||
326				character === '\r' ||
327				character === '\f' ||
328				character === '\v';
329			if (white) {
330				if (current !== '') parts.push(current);
331				current = '';
332				continue;
333			}
334			current += character;
335		}
336		if (current !== '') parts.push(current);
337		return parts.join(' ');
338	}
339	
340	type Segment = Readonly<{ kind: 'text' | 'expression'; value: string }>;
341	
342	function messageSegments(node: Node | undefined, source: string): Segment[] {
343		if (node === undefined) return [];
344		if (node.type === 'Literal' && typeof node.value === 'string')
345			return [{ kind: 'text', value: node.value }];
346		if (node.type === 'TemplateLiteral') {
347			const quasis = (node.quasis ?? []) as Node[];
348			const expressions = (node.expressions ?? []) as Node[];
349			const segments: Segment[] = [];
350			for (let index = 0; index < quasis.length; index += 1) {
351				const quasi = quasis[index] as Node | undefined;
352				const cooked = (quasi?.value as { cooked?: string } | undefined)?.cooked ?? '';
353				if (cooked !== '') segments.push({ kind: 'text', value: cooked });
354				const expression = expressions[index];
355				if (expression !== undefined)
356					segments.push({
357						kind: 'expression',
358						value: collapseWhitespace(source.slice(expression.start, expression.end)),
359					});
360			}
361			return segments;
362		}
363		if (node.type === 'BinaryExpression' && node.operator === '+')
364			return [
365				...messageSegments(node.left as Node | undefined, source),
366				...messageSegments(node.right as Node | undefined, source),
367			];
368		return [{ kind: 'expression', value: collapseWhitespace(source.slice(node.start, node.end)) }];
369	}
370	
371	function renderSegments(segments: readonly Segment[]): string {
372		return segments
373			.map((segment) => (segment.kind === 'text' ? segment.value : `\${${segment.value}}`))
374			.join('');
375	}
376	
377	function lineOf(source: string, offset: number): number {
378		let line = 1;
379		for (let index = 0; index < offset && index < source.length; index += 1)
380			if (source[index] === '\n') line += 1;
381		return line;
382	}
383	
384	const FUNCTION_TYPES: readonly string[] = Object.freeze([
385		'FunctionDeclaration',
386		'FunctionExpression',
387		'ArrowFunctionExpression',
388	]);
389	
390	function enclosingName(ancestors: readonly Node[]): string {
391		for (let index = ancestors.length - 1; index >= 0; index -= 1) {
392			const node = ancestors[index] as Node;
393			if (node.type === 'FunctionDeclaration') {
394				const id = node.id as Node | undefined;
395				const name = id === undefined ? null : (id.name as string | undefined);
396				if (name !== undefined && name !== null) return name;
397			}
398			if (node.type === 'VariableDeclarator') {
399				const id = node.id as Node | undefined;
400				const name = id === undefined ? null : (id.name as string | undefined);
401				if (name !== undefined && name !== null) return name;
402			}
403			if (node.type === 'MethodDefinition' || node.type === 'Property') {
404				const key = node.key as Node | undefined;
405				const name = key === undefined ? null : (key.name as string | undefined);
406				if (name !== undefined && name !== null) return name;
407			}
408		}
409		return 'module scope';
410	}
411	
412	function guardOf(
413		ancestors: readonly Node[],
414		site: Node,
415		source: string,
416	): { condition: string; conditionForm: CensusEntry['conditionForm'] } {
417		for (let index = ancestors.length - 1; index >= 0; index -= 1) {
418			const node = ancestors[index] as Node;
419			if (FUNCTION_TYPES.includes(node.type)) break;
420			if (node.type !== 'IfStatement') continue;
421			const test = node.test as Node;
422			const consequent = node.consequent as Node | undefined;
423			const inConsequent =
424				consequent !== undefined &&
425				site.start >= consequent.start &&
426				site.end <= consequent.end;
427			return {
428				condition: collapseWhitespace(source.slice(test.start, test.end)),
429				conditionForm: inConsequent ? 'if-consequent' : 'if-alternate',
430			};
431		}
432		return {
433			condition: `unconditional within ${enclosingName(ancestors)}`,
434			conditionForm: 'unconditional',
435		};
436	}
437	
438	const SLUG_LIMIT = 64;
439	
440	/** A stable, readable identifier derived from the site's own first words. */
441	export function slugOf(value: string): string {
442		let slug = '';
443		let pendingSeparator = false;
444		for (const character of value.toLowerCase()) {
445			const code = character.charCodeAt(0);
446			const alphanumeric = (code >= 97 && code <= 122) || (code >= 48 && code <= 57);
447			if (!alphanumeric) {
448				pendingSeparator = slug !== '';
449				continue;
450			}
451			if (pendingSeparator) {
452				if (slug.length >= SLUG_LIMIT) break;
453				slug += '-';
454				pendingSeparator = false;
455			}
456			if (slug.length >= SLUG_LIMIT) break;
457			slug += character;
458		}
459		return slug === '' ? 'unnamed' : slug;
460	}
461	
462	async function readEntries(directory: string) {
463		try {
464			return await readdir(directory, { withFileTypes: true });
465		} catch {
466			return [];
467		}
468	}
469	
470	async function typeScriptFilesBelow(directory: string): Promise<string[]> {
471		const files: string[] = [];
472		const entries = await readEntries(directory);
473		for (const entry of entries.sort((left, right) => (left.name < right.name ? -1 : 1))) {
474			if (
475				entry.name === 'node_modules' ||
476				entry.name === '.git' ||
477				entry.name === 'dist' ||
478				entry.name === 'test'
479			)
480				continue;
481			const item = path.join(directory, entry.name);
482			if (entry.isDirectory()) {
483				files.push(...(await typeScriptFilesBelow(item)));
484				continue;
485			}
486			if (entry.isFile() && path.extname(entry.name) === '.ts') files.push(item);
487		}
488		return files;
489	}
490	
491	type Site = Readonly<{
492		node: Node;
493		ancestors: readonly Node[];
494		kind: 'refuse-call' | 'throw-error';
495		argument: Node | undefined;
496		properties: Readonly<Record<string, Node>>;
497	}>;
498	
499	function propertiesOf(node: Node | undefined): Readonly<Record<string, Node>> {
500		if (node === undefined || node.type !== 'ObjectExpression') return {};
501		const record: Record<string, Node> = {};
502		for (const property of (node.properties ?? []) as Node[]) {
503			if (property.type !== 'Property') continue;
504			const key = property.key as Node | undefined;
505			const name = key === undefined ? undefined : (key.name as string | undefined);
506			const value = property.value as Node | undefined;
507			if (name !== undefined && value !== undefined) record[name] = value;
508		}
509		return record;
510	}
511	
512	type RecordedSite = Readonly<{ node: Node; callee: string; argument: Node | undefined }>;
513	
514	/**
515	 * Call sites named `refuse` or `refused` inside a frozen subtree.
516	 *
517	 * These are refusals the adapters *record* rather than throw — a local helper
518	 * appends a reason to a per-file refusal list, and the caller decides what to
519	 * do with it. They do not carry the pipeline's `{ code, message, stage, origin }`
520	 * shape, so the census does not pretend to have read one. What it does is count
521	 * and locate them, so the gap is a number instead of an absence.
522	 */
523	const RECORDED_REFUSAL_CALLEES: readonly string[] = Object.freeze(['refuse', 'refused']);
524	
525	function collectSites(
526		root: Node,
527		structured: boolean,
528	): { sites: Site[]; recorded: RecordedSite[] } {
529		const sites: Site[] = [];
530		const recorded: RecordedSite[] = [];
531		const walk = (node: Node, ancestors: Node[]): void => {
532			if (node.type === 'ThrowStatement') {
533				const argument = node.argument as Node | undefined;
534				const callee =
535					argument === undefined ? undefined : (argument.callee as Node | undefined);
536				if (
537					argument?.type === 'NewExpression' &&
538					callee?.type === 'Identifier' &&
539					callee.name === 'Error'
540				)
541					sites.push({
542						node,
543						ancestors: [...ancestors],
544						kind: 'throw-error',
545						argument: ((argument.arguments ?? []) as Node[])[0],
546						properties: {},
547					});
548			}
549			if (node.type === 'CallExpression') {
550				const callee = node.callee as Node | undefined;
551				const name = callee?.type === 'Identifier' ? (callee.name as string) : null;
552				if (name !== null && RECORDED_REFUSAL_CALLEES.includes(name)) {
553					const args = (node.arguments ?? []) as Node[];
554					if (structured && name === 'refuse')
555						sites.push({
556							node,
557							ancestors: [...ancestors],
558							kind: 'refuse-call',
559							argument: args[0],
560							properties: propertiesOf(args[0]),
561						});
562					else recorded.push({ node, callee: name, argument: args[args.length - 1] });
563				}
564			}
565			ancestors.push(node);
566			for (const key of Object.keys(node)) {
567				if (key === 'type' || key === 'start' || key === 'end') continue;
568				const value = node[key];
569				if (Array.isArray(value)) {
570					for (const item of value) if (isNode(item)) walk(item, ancestors);
571					continue;
572				}
573				if (isNode(value)) walk(value, ancestors);
574			}
575			ancestors.pop();
576		};
577		walk(root, []);
578		return { sites, recorded };
579	}
580	
581	function staticStringOf(node: Node | undefined, source: string): string | null {
582		const segments = messageSegments(node, source);
583		if (segments.length === 0) return null;
584		return segments.every((segment) => segment.kind === 'text') ? renderSegments(segments) : null;
585	}
586	
587	const compareEntries = (left: CensusEntry, right: CensusEntry): number => {
588		if (left.file !== right.file) return left.file < right.file ? -1 : 1;
589		return left.line - right.line;
590	};
591	
592	/** Derive the census from the checkout. Frozen paths are read, never written. */
593	export async function buildRefusalCensus(rootDir = '.'): Promise<RefusalCensus> {
594		const root = path.resolve(rootDir);
595		const modules = new Map(CENSUS_MODULES.map((module) => [module.file, module]));
596		const entries: CensusEntry[] = [];
597		const recordedRefusals: RecordedRefusal[] = [];
598		const usedCodes = new Map<string, number>();
599		let filesScanned = 0;
600		const unlisted: string[] = [];
601		for (const scanned of CENSUS_ROOTS) {
602			const scanRoot = path.join(root, scanned.root);
603			for (const file of await typeScriptFilesBelow(scanRoot)) {
604				const relative = path.relative(root, file);
605				const source = await readFile(file, 'utf8');
606				filesScanned += 1;
607				const collected = collectSites(
608					analyze(source, { path: relative }).ast as unknown as Node,
609					scanned.origin === 'pipeline',
610				);
611				for (const site of collected.recorded) {
612					const segments = messageSegments(site.argument, source);
613					if (segments.length === 0) continue;
614					recordedRefusals.push(
615						Object.freeze({
616							callee: site.callee,
617							message: renderSegments(segments),
618							messageForm: segments.every((segment) => segment.kind === 'text')
619								? ('static' as const)
620								: ('composed' as const),
621							origin: scanned.origin,
622							file: relative,
623							line: lineOf(source, site.node.start),
624							enclosing: 'recorded through a local helper',
625						}),
626					);
627				}
628				const sites = collected.sites;
629				if (sites.length === 0) continue;
630				const module = modules.get(relative);
631				if (module === undefined) {
632					unlisted.push(relative);
633					continue;
634				}
635				for (const site of sites) {
636					const messageNode =
637						site.kind === 'refuse-call' ? site.properties.message : site.argument;
638					const segments = messageSegments(messageNode, source);
639					const message = renderSegments(segments);
640					const staticSegments = segments
641						.filter((segment) => segment.kind === 'text')
642						.map((segment) => segment.value.trim())
643						.filter((segment) => segment !== '');
644					const declaredCode =
645						site.kind === 'refuse-call'
646							? staticStringOf(site.properties.code, source)
647							: null;
648					const declaredStage =
649						site.kind === 'refuse-call'
650							? staticStringOf(site.properties.stage, source)
651							: null;
652					const declaredOrigin =
653						site.kind === 'refuse-call'
654							? staticStringOf(site.properties.origin, source)
655							: null;
656					const stem = path.basename(relative, '.ts');
657					const fallback = `${module.origin === 'pipeline' ? 'pipeline' : 'frozen'}.${stem}.${slugOf(staticSegments[0] ?? message)}`;
658					const baseCode = declaredCode ?? fallback;
659					const seen = usedCodes.get(baseCode) ?? 0;
660					usedCodes.set(baseCode, seen + 1);
661					const code = seen === 0 ? baseCode : `${baseCode}-${String(seen + 1)}`;
662					const classification: CensusEntry['classification'] =
663						site.kind === 'refuse-call'
664							? 'refusal'
665							: module.origin === 'pipeline'
666								? 'defect'
667								: (staticSegments[0] ?? '').startsWith('Refused:')
668									? 'refusal'
669									: 'unclassified';
670					const guard = guardOf(site.ancestors, site.node, source);
671					entries.push(
672						Object.freeze({
673							code,
674							message,
675							messageForm: segments.every((segment) => segment.kind === 'text')
676								? ('static' as const)
677								: ('composed' as const),
678							staticSegments: Object.freeze(staticSegments),
679							classification,
680							condition: guard.condition,
681							conditionForm: guard.conditionForm,
682							origin:
683								declaredOrigin === 'frozen-adapter' || declaredOrigin === 'pipeline'
684									? declaredOrigin
685									: module.origin,
686							stage: declaredStage ?? module.stage,
687							stageBasis: module.stageBasis,
688							file: relative,
689							line: lineOf(source, site.node.start),
690							enclosing: enclosingName(site.ancestors),
691						}),
692					);
693				}
694			}
695		}
696		if (unlisted.length > 0)
697			throw new Error(
698				`refusal-census: ${String(unlisted.length)} scanned file(s) raise refusals and are not declared in CENSUS_MODULES: ${unlisted.sort().join(', ')}. Declare the module and the basis for its stage reading rather than let the census drop the sites.`,
699			);
700		entries.sort(compareEntries);
701		recordedRefusals.sort((left, right) =>
702			left.file === right.file ? left.line - right.line : left.file < right.file ? -1 : 1,
703		);
704		const byOrigin: Record<string, number> = {};
705		const byClassification: Record<string, number> = {};
706		const byStage: Record<string, number> = {};
707		for (const entry of entries) {
708			byOrigin[entry.origin] = (byOrigin[entry.origin] ?? 0) + 1;
709			byClassification[entry.classification] = (byClassification[entry.classification] ?? 0) + 1;
710			byStage[entry.stage] = (byStage[entry.stage] ?? 0) + 1;
711		}
712		const sortedRecord = (record: Record<string, number>): Readonly<Record<string, number>> =>
713			Object.freeze(
714				Object.fromEntries(
715					Object.keys(record)
716						.sort((left, right) => (left < right ? -1 : 1))
717						.map((key) => [key, record[key] as number]),
718				),
719			);
720		return Object.freeze({
721			schemaVersion: REFUSAL_CENSUS_SCHEMA,
722			generatedBy: 'versionless refusal-census',
723			adapterFreezeComposite: ADAPTER_FREEZE_COMPOSITE,
724			roots: Object.freeze(CENSUS_ROOTS.map((scanned) => scanned.root)),
725			filesScanned,
726			summary: Object.freeze({
727				sites: entries.length,
728				byOrigin: sortedRecord(byOrigin),
729				byClassification: sortedRecord(byClassification),
730				byStage: sortedRecord(byStage),
731				distinctCodes: new Set(entries.map((entry) => entry.code)).size,
732				recordedRefusalSites: recordedRefusals.length,
733			}),
734			entries: Object.freeze(entries),
735			recordedRefusals: Object.freeze(recordedRefusals),
736			notEstablished: CENSUS_NOT_ESTABLISHED,
737		});
738	}
739	
740	/** Write the census where the trust surfaces and the fleet report can read it. */
741	export async function writeRefusalCensus(
742		census: RefusalCensus,
743		file = REFUSAL_CENSUS_FILE,
744	): Promise<string> {
745		const target = path.resolve(file);
746		await mkdir(path.dirname(target), { recursive: true });
747		await writeFile(target, `${JSON.stringify(census, null, '\t')}\n`);
748		return file;
749	}
